using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;

// Demonstrates EF Core 9 Cosmos DB breaking change fixes.
// Apply these patterns in your separate Cosmos DB project.

class CosmosDbContext : DbContext
{
    public DbSet<Session> Sessions => Set<Session>();
    public DbSet<Product> Products => Set<Product>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF9 breaking change #1: Default discriminator renamed from "Discriminator" to "$type".
        // Existing documents use the old property name — configure explicitly to preserve compatibility.
        modelBuilder.Entity<Session>().HasDiscriminator<string>("Discriminator");
        modelBuilder.Entity<Product>().HasDiscriminator<string>("Discriminator");

        // EF9 breaking change #2: id property no longer contains the discriminator prefix.
        // Existing documents have "Product|123" format. Preserve it so point-reads still work.
        modelBuilder.Entity<Product>().HasRootDiscriminatorInJsonId(true);
    }
}

class Session { public string Id { get; set; } = ""; public string Name { get; set; } = ""; }
class Product { public string Id { get; set; } = ""; public string Title { get; set; } = ""; }

// EF9 breaking change #3: Sync I/O on Cosmos provider now throws.
// All queries and saves must use async equivalents.
class CosmosQueryService
{
    private readonly CosmosDbContext _db;
    public CosmosQueryService(CosmosDbContext db) => _db = db;

    // WRONG (throws in EF9):
    //   var items = _db.Products.ToList();
    //   _db.SaveChanges();

    // CORRECT — use async:
    public async Task<List<Product>> GetProductsAsync()
        => await _db.Products.ToListAsync();

    public async Task SaveAsync()
        => await _db.SaveChangesAsync();
}

